from collections import defaultdict
from itertools import combinations
for file_entry in code_payload['data']['files']:
    class_hierarchies = defaultdict(list)
    method_sets = {}
    for cls in file_entry['classes']:
        if any(base.endswith('Exception') for base in cls['bases']) or cls['name'].endswith('Mixin'):
            continue
        for base in cls['bases']:
            class_hierarchies[base].append(cls['name'])
        method_sets[cls['name']] = frozenset(cls['class_methods'])
    for hier1, hier2 in combinations(class_hierarchies.values(), 2):
        if len(hier1) <= 1 or len(hier2) <= 1:
            continue
        if not any(h1.replace(hier1[0], '') == h2.replace(hier2[0], '') for h1 in hier1 for h2 in hier2):
            continue
        if hier1[0] not in method_sets or hier2[0] not in method_sets:
            continue
        union = method_sets[hier1[0]] | method_sets[hier2[0]]
        if not union:
            continue
        similarity = len(method_sets[hier1[0]] & method_sets[hier2[0]]) / len(union)
        if similarity > PARALLEL_INHERITANCE_SIMILARITY_THRESHOLD:
            emit a high-severity flag describing the pair hier1[0]/hier2[0] with similarity and file_entry['path']

