            continue
        if any(base.name.endswith('Exception') for base in cls.bases if isinstance(base, nodes.Name)):
            continue
        getters = 0
        setters = 0
        others = 0
        for method in cls.mymethods():
            if method.name.startswith('__'):
                continue
            if method.name.startswith('get_') and len(method.body) == 1:
                getters += 1
            elif method.name.startswith('set_') and len(method.body) == 1:
                setters += 1
            else:
                others += 1
        if (others == 0 and getters + setters >= DATA_CLASS_METHODS and
                not cls.name.endswith(('DTO', 'Model', 'Entity', 'Record'))):
            emit a medium-severity flag for cls.name at module_record.file_path with getline cls.lineno and counts of getters/setters

defined_functions = {}
for module_record in parsed_modules:
    called_functions = set()
    exported_functions = set()
    for func_node in module_record.body:
        if not isinstance(func_node, nodes.FunctionDef):
            continue
        if func_node.name.startswith('test_'):
            continue
        decorator_names = [getattr(deco, 'name', None) or getattr(deco, 'attrname', None)
                           for deco in (func_node.decorators.nodes if func_node.decorators else [])]
        if 'property' in decorator_names:
            continue
        has_public_decorator = any(name and any(trigger in name for trigger in ['api', 'route', 'endpoint', 'public', 'export'])
                                   for name in decorator_names)
        defined_functions[func_node.name] = has_public_decorator
        if (not func_node.name.startswith('_') or func_node.name.startswith('__')):
            exported_functions.add(func_node.name)
        for call in func_node.nodes_of_class(nodes.Call):
            if isinstance(call.func, nodes.Name):
                called_functions.add(call.func.name)
            elif isinstance(call.func, nodes.Attribute):
                called_functions.add(call.func.attrname)
    unused_functions = {name for name, is_public in defined_functions.items()
                        if name not in called_functions and not is_public and name not in exported_functions}
    if len(unused_functions) >= DEAD_CODE_THRESHOLD:
        emit a low-severity flag listing unused_functions for module_record.file_path

