                if (isinstance(decorator, nodes.Name) and decorator.name == 'property') or \
                   (isinstance(decorator, nodes.Call) and isinstance(decorator.func, nodes.Name) and decorator.func.name == 'property') or \
                   (isinstance(decorator, nodes.Attribute) and decorator.attrname == 'property'):
                    is_property = True
                    break
        if is_property or (len(func.body) == 1 and isinstance(func.body[0], nodes.Return)):
