                    local_calls += 1
                else:
                    if attr.expr.name.lower() not in {'logger', 'config', 'utils', 'helper'}:
                        class_calls[attr.expr.name] += 1
        if class_calls:
            max_class, max_calls = max(class_calls.items(), key=lambda kv: kv[1])
