        delegating_methods = 0
        delegate_targets = defaultdict(list)
        for method in methods:
            if method.decorators and any(
                isinstance(deco, nodes.Name) and deco.name == 'property' or
                isinstance(deco, nodes.Call) and isinstance(deco.func, nodes.Name) and deco.func.name == 'property' or
