                    delegating_methods += 1
                    if isinstance(return_value.func, nodes.Attribute):
                        target = return_value.func.expr.as_string()
                        delegate_targets[target].append(method.name)
        delegation_ratio = delegating_methods / total_methods if total_methods else 0
        if (delegation_ratio > MIDDLE_MAN_RATIO and
