adj = build adjacency map from edges
cycles = find all simple cycles in adj
cycle_groups = {}
for cycle in cycles:
    if MIN_CYCLE_SIZE <= len(cycle) <= MAX_CYCLE_SIZE:
        if any(excluded in node.lower() for excluded in CYCLE_EXCLUDED_MODULES for node in cycle):
            continue
        strength = 0
        for i in range(len(cycle)):
            node1 = cycle[i]
            node2 = cycle[(i + 1) % len(cycle)]
            strength += count all simple paths from node1 to node2 using adj
        key = frozenset(cycle)
        cycle_groups.setdefault(key, []).append((cycle, strength))
for group in cycle_groups.values():
    cycle, strength = max(group, key=lambda entry: entry[1])
    severity = "high" if len(cycle) >= CYCLE_HIGH_MIN_SIZE and strength >= CYCLE_HIGH_MIN_STRENGTH else "medium"
    report = {
        "module": cycle[0],
        "file_path": architectural.data.module_file_paths.get(cycle[0], "Unknown"),
        "cycle_size": len(cycle),
        "cycle_strength": strength,
        "severity": severity
    }
    emit report

