threshold = LCOM_THRESHOLD
for class_name, info in structural.data.class_info.items():
    method_names = info.get('class_methods', [])
    fields = set(info.get('fields', []))
    if len(method_names) < 2:
        continue
    regular_methods = [name for name in method_names if not name.startswith('__')]
    if len(regular_methods) < 2:
        continue
    field_usage = {method: set() for method in regular_methods}
    call_relations = info.get('class_method_call_relations', {})
    for method in regular_methods:
        for field in fields:
            if field in call_relations.get(method, []):
                field_usage[method].add(field)
    changed = True
    while changed:
        changed = False
        for method in regular_methods:
            current = field_usage[method] 
            for callee in call_relations.get(method, []):
                if callee in field_usage:
                    new_fields = field_usage[callee] - current
                    if new_fields:
                        field_usage[method].update(new_fields)
                        changed = True
    non_cohesive = 0
    cohesive = 0
    for i, method1 in enumerate(regular_methods):
        for method2 in regular_methods[i+1:]:
            if method1.startswith('_') and method2.startswith('_'):
                continue
            shared = field_usage[method1] & field_usage[method2]
            if shared:
                cohesive += 1
            else:
                non_cohesive += 1
    if non_cohesive == 0 and cohesive == 0:
        continue
    lcom = max(0, non_cohesive - cohesive)
    if lcom <= threshold:
        continue
    severity = 'High' if lcom > threshold * 1.5 else 'Medium'
    module_name = class_name.rsplit('.', 1)[0]
    file_path = structural.data.module_file_paths.get(module_name, 'Unknown')
    emit finding with module_class=class_name, lcom, severity, and file_path

