from collections import deque

def shortest_path_length(start, target):
    queue = deque([(start, 0)])
    visited = {start}
    while queue:
        node, depth = queue.popleft()
        if node == target:
            return depth
        for successor in graph.get(node, ()): 
            if successor not in visited:
                visited.add(successor)
                queue.append((successor, depth + 1))
    raise ValueError('no path')

for class_name in graph:
    if class_name == 'object':
        continue
    try:
        depth = shortest_path_length('object', class_name)
    except ValueError:
        continue
    if depth <= DIT_THRESHOLD:
        continue
    severity = 'High' if depth > DIT_THRESHOLD * 1.5 else 'Medium'
    module_name = class_name.rsplit('.', 1)[0]
    file_path = structural.data.module_file_paths.get(module_name, 'Unknown')
    emit finding for class_name with depth, severity, file_path

