encodings = ['utf-8', 'utf-8-sig', 'latin1', 'cp1252']
for module_name, info in structural.data.module_info.items():
    file_path = structural.data.module_file_paths.get(module_name, '')
    if not file_path:
        continue
    content = None
    for encoding in encodings:
        try:
            with open(file_path, 'r', encoding=encoding) as f:
                content = f.read()
            break
        except UnicodeDecodeError:
            continue
    if content is None:
        continue
    lines = [line.strip() for line in content.splitlines()]
    meaningful = 0
    in_doc = False
    for line in lines:
        if not line or line.startswith('#'):
            continue
        if line.startswith('"""') or line.startswith("'''"):
            in_doc = not in_doc
            continue
        if in_doc:
            continue
        meaningful += 1
    threshold = MAX_FILE_LENGTH
    if meaningful <= threshold:
        continue
    severity = 'High' if meaningful > threshold * 1.5 else 'Medium'
    emit finding for module_name with meaningful, threshold, severity, file_path

exclude_prefixes = tuple(BRANCH_EXCLUDE_METHOD_PREFIXES)
exclude_decorators = set(BRANCH_EXCLUDE_DECORATORS)
for class_name, info in structural.data.class_info.items():
    for method in info.get('class_methods', []):
        if method.startswith(exclude_prefixes):
            continue
        decorator_names = info.get('method_decorators', {}).get(method, [])
        if any(name in exclude_decorators for name in decorator_names):
            continue
        branch_count = 0
        max_nesting = 0
        current_nesting = 0
        for node in structural.data.method_ast_nodes.get(method, []):
            if node in {'If', 'For', 'While', 'Try'}:
                branch_count += 1
                current_nesting += 1
                max_nesting = max(max_nesting, current_nesting)
                if node == 'If':
                    branch_count += node.orelse_if_count
                elif node == 'Try':
                    branch_count += node.handler_count
            elif node == 'FunctionDef' and node != method:
                current_nesting = max(0, current_nesting - 1)
        threshold = MAX_BRANCHES
        nesting_limit = MAX_NESTING_DEPTH
        if branch_count > threshold or max_nesting > nesting_limit:
            severity = 'High' if branch_count > threshold * 1.5 else 'Medium'
            file_path = structural.data.module_file_paths.get(class_name.rsplit('.', 1)[0], 'Unknown')
            emit finding for class_name.method with branch_count, max_nesting, severity, file_path
